def is_ui_key(key: str) -> bool:
    if not key or len(key.strip()) < 2:
        return False
    if re.fullmatch(r"[\s\W\d]+", key):
        return False
    if key in {"@alexmorgan", "@fangeosports", "you@email.com"}:
        return False
    return True


def merge_key(strings: dict, key: str, values: dict[str, str]) -> None:
    """Merge locale values into the catalog.

    Never invent ``en = key`` — that previously overwrote real English copy with
    raw snake_case keys (e.g. ``home_crowd`` rendered literally in Profile).
    Never replace an existing non-key translation with a value that equals the key.
    """
    entry = strings.setdefault(key, {})
    locs = entry.setdefault("localizations", {})
    for lang in SUPPORTED:
        if lang not in values:
            continue
        new_val = values[lang]
        existing = None
        try:
            existing = locs[lang]["stringUnit"]["value"]
        except Exception:
            existing = None
        if (
            isinstance(new_val, str)
            and new_val == key
            and isinstance(existing, str)
            and existing.strip()
            and existing != key
        ):
            continue
        locs[lang] = unit(new_val)
    entry["extractionState"] = "manual"


def catalog_entry_count(strings: dict) -> int:
    return len(strings)


def supported_locale_coverage(strings: dict) -> dict[str, int]:
    coverage = {lang: 0 for lang in SUPPORTED}
    for entry in strings.values():
        locs = entry.get("localizations") or {}
        for lang in SUPPORTED:
            try:
                val = locs[lang]["stringUnit"]["value"]
            except Exception:
                continue
            if isinstance(val, str) and val.strip():
                coverage[lang] += 1
    return coverage


def main() -> None:
    data = json.loads(XCSTRINGS.read_text(encoding="utf-8"))
    strings = data.setdefault("strings", {})
    before_count = catalog_entry_count(strings)
    before_coverage = supported_locale_coverage(strings)
    before_keys = set(strings.keys())

    added_keys = 0
    completed_locales = 0

    for key, values in SEMANTIC.items():
        before = set(strings.get(key, {}).get("localizations", {}).keys())
        merge_key(strings, key, values)
        after = set(strings.get(key, {}).get("localizations", {}).keys())
        if key not in before:
            added_keys += 1
        completed_locales += len(after - before)

    # Load optional bulk English-key translations
    bulk_paths = [
        Path(__file__).with_name("ui_translations_bulk.json"),
        Path(__file__).with_name("ui_hand_translations.json"),
    ]
    for bulk_path in bulk_paths:
        if not bulk_path.exists():
            continue
        bulk = json.loads(bulk_path.read_text(encoding="utf-8"))
        for key, values in bulk.items():
            if not is_ui_key(key):
                continue
            before = set(strings.get(key, {}).get("localizations", {}).keys())
            merge_key(strings, key, values)
            after = set(strings.get(key, {}).get("localizations", {}).keys())
            completed_locales += len(after - before)

    after_count = catalog_entry_count(strings)
    after_coverage = supported_locale_coverage(strings)
    after_keys = set(strings.keys())
    deleted = sorted(before_keys - after_keys)
    deleted_pct = (len(deleted) / before_count * 100.0) if before_count else 0.0

    # Safety rails: this script must only merge/enrich. Never accept a mass delete.
    if deleted:
        raise SystemExit(
            f"Refusing to write Localizable.xcstrings: merge unexpectedly deleted "
            f"{len(deleted)} keys ({deleted_pct:.1f}%). First: {deleted[:10]}"
        )
    if after_count < before_count:
        raise SystemExit(
            f"Refusing to write Localizable.xcstrings: entry count dropped "
            f"{before_count} -> {after_count}."
        )
    for lang in SUPPORTED:
        if before_coverage[lang] > 0 and after_coverage[lang] < int(before_coverage[lang] * 0.9):
            raise SystemExit(
                f"Refusing to write Localizable.xcstrings: locale '{lang}' coverage dropped "
                f"{before_coverage[lang]} -> {after_coverage[lang]}."
            )

    XCSTRINGS.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Semantic keys merged: {len(SEMANTIC)}")
    print(f"New semantic keys: {added_keys}")
    print(f"Locale entries added: {completed_locales}")
    print(f"Catalog entries: {before_count} -> {after_count}")


if __name__ == "__main__":
    main()
